function resolveStaffmodSkill(text,slot=''){
 const q=String(text||'').trim().toLowerCase(); if(!q)return null;
 let best=null;
 for(const s of STAFFMOD_SKILLS){if(slot&&s.slots?.length&&!s.slots.includes(slot))continue;for(const a of [s.ko,s.en,...(s.aliases||[])]){const aa=String(a||'').toLowerCase();if(!aa)continue;if(q.includes(aa)||aa.includes(q)){const rank=aa.length+(q===aa?50:0);if(!best||rank>best.rank)best={...s,rank};}}}
 return best;
}
